-- CAB-0015: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0015: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('akmal-nasrullah-mohd-nasir','mustapha-sakmud') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0015: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('johor bahru','sepanggar') and slug not in ('akmal-nasrullah-mohd-nasir','mustapha-sakmud')) then raise exception 'CAB-0015: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0015:%' and (m.source_type <> 'editorial' or e.slug not in ('akmal-nasrullah-mohd-nasir','mustapha-sakmud') or m.import_key not like 'CAB-0015:' || e.slug || ':%')) then raise exception 'CAB-0015: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'akmal-nasrullah-mohd-nasir','Akmal Nasrullah Mohd Nasir','government','Minister of Economy','Johor Bahru','Johor','Akmal Nasrullah Mohd Nasir is Minister of Economy. He represents Johor Bahru, Johor, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://www.ekonomi.gov.my/','/portraits/akmal-nasrullah-mohd-nasir.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P160.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Johor Bahru", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4199"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'mustapha-sakmud','Mustapha Sakmud','government','Minister in the Prime Minister’s Department (Sabah and Sarawak)','Sepanggar','Sabah','Mustapha Sakmud is Minister in the Prime Minister’s Department (Sabah and Sarawak). He represents Sepanggar, Sabah, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://bhess.jpm.gov.my/','/portraits/mustapha-sakmud.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P171.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Sepanggar", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4210"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('akmal-nasrullah-mohd-nasir','mustapha-sakmud') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0015: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0015:akmal-nasrullah-mohd-nasir:kl20-vc-700m-2030','Attract RM700 million in venture-capital investment through KL20 by 2030','Economy','in_progress',null,'2030-12-31','2026-10-14','https://web26.bernama.com/en/region/news.php?id=2620217','2026-10-19','https://web26.bernama.com/en/region/news.php?id=2622558','Akmal set a KL20 target of RM700 million in venture-capital investment by 2030.','His 19 October update describes continued startup support. Broader investment and sales-proceeds totals in that report are not comparable to this specific venture-capital target. No target-specific completion percentage is inferred.','2026-11-09','editorial',false from public.entities e where e.slug='akmal-nasrullah-mohd-nasir' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.