insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0015:mustapha-sakmud:ma63-dashboard-launch','Launch the first phase of the public MA63 progress dashboard','Governance','achieved',null,'2026-01-31','2026-01-01','https://www.bernama.com/tv/news.php?id=2507928','2026-01-28','https://www.bernama.com/bm/am/news.php?id=2517860','Mustapha announced that the public dashboard for tracking MA63 implementation would be made available by the end of January 2026.','The 28 January launch report confirms public access to Phase 1 through BHESS, launched by Fadillah Yusof. Achieved covers this shared dashboard launch only, not Phase 2 integration or settlement of MA63 demands. No sole personal credit or completion percentage is implied.','2026-11-09','editorial',false from public.entities e where e.slug='mustapha-sakmud' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milesto